import { Group, Vector3, Euler } from 'three/webgpu';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as text from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {Object} assets
 * @property {string} [assets.meshUrl]
 * @property {{x:number,y:number,z:number}} position
 * @property {{x:number,y:number,z:number}} rotation
 * @property {{x:number,y:number,z:number}} scale
 * @property {Array<{name:string,params:any}>} cinematicPrimitives
 */

/**
 * @typedef {Object} NodeContext
 * @property {(url:string)=>any} glbLoader   // synchronous loader returning a THREE.Object3D
 * @property {(event:string,detail:any)=>void} [emit] // optional event emitter
 * @property {Record<string,Function>} primitives
 */

/**
 * Creates the ornamental divider node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  // Root container
  const root = new Group();
  root.name = 'ornamental-divider';

  // Load GLB mesh (synchronous via context loader)
  const meshUrl = (config.assets && config.assets.meshUrl) || '';
  const glb = meshUrl ? ctx.glbLoader(meshUrl) : new Group();
  glb.traverse((child) => {
    if (child.isMesh) {
      child.castShadow = true;
      child.receiveShadow = true;
    }
  });
  root.add(glb);

  // Apply transform from config
  const pos = config.position || { x: 0, y: 0, z: 0 };
  const rot = config.rotation || { x: 0, y: 0, z: 0 };
  const scl = config.scale || { x: 1, y: 1, z: 1 };
  root.position.set(pos.x, pos.y, pos.z);
  root.rotation.set(rot.x, rot.y, rot.z);
  root.scale.set(scl.x, scl.y, scl.z);

  // Apply cinematic primitives if any (none for this node, but kept for consistency)
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const primitive of config.cinematicPrimitives) {
      const fn = ctx.primitives[primitive.name];
      if (typeof fn === 'function') {
        fn(root, primitive.params);
      }
    }
  }

  // Interaction state
  const originalY = root.position.y;
  let hoverTween = null;

  // Event handlers attached to userData
  root.userData.handlers = {
    hover: (event) => {
      // event.type could be 'enter' or 'leave' – handle both
      if (event && event.type === 'enter') {
        // Rise‑in effect (subtle, 0.15 scene units)
        if (hoverTween) hoverTween.kill();
        hoverTween = gsap.to(root.position, {
          y: originalY + 0.15,
          duration: 0.15,
          ease: 'power3.out',
        });
      } else if (event && event.type === 'leave') {
        if (hoverTween) hoverTween.kill();
        hoverTween = gsap.to(root.position, {
          y: originalY,
          duration: 0.15,
          ease: 'power3.out',
        });
      }
    },
    click: (event) => {
      // Emit navigation/event signal
      if (typeof ctx.emit === 'function') {
        ctx.emit('hub-home.select', { source: root });
      }
    },
    press: (event) => {
      // Press‑down visual feedback (scale 0.97 briefly)
      gsap.to(root.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out(1.7)',
        onComplete: () => {
          gsap.to(root.scale, {
            x: 1,
            y: 1,
            z: 1,
            duration: 0.12,
            ease: 'back.out(1.7)',
          });
        },
      });
    },
  };

  // Cleanup routine
  root.userData.cleanup = () => {
    // Kill any GSAP tweens tied to this object
    gsap.killTweensOf(root.position);
    gsap.killTweensOf(root.scale);
    // Dispose geometries and materials from the loaded GLB
    glb.traverse((child) => {
      if (child.isMesh) {
        if (child.geometry) child.geometry.dispose();
        if (Array.isArray(child.material)) {
          child.material.forEach((m) => m && m.dispose && m.dispose());
        } else if (child.material) {
          child.material.dispose();
        }
      }
    });
    // Remove from parent if attached
    if (root.parent) root.parent.remove(root);
  };

  return root;
}
